python3 - <<'PY'
import limited_client as robot, numpy as np
for cam in (0,2):
 obs=robot.observe(camera=cam); print('\nCAM',cam,'robot',obs['robot'])
 if cam==0:
  print('T',obs['camera_to_world'])
  print('K',obs['intrinsic'])
  dep=obs['depth_m']; K=obs['intrinsic']; T=obs['camera_to_world']
  for y in (80,110,140,170,200):
   vals=[]
   for x in (270,300,330,360,390):
    d=float(dep[y,x])
    if np.isfinite(d) and d>0:
     w=T@np.array([(x-K[0,2])*d/K[0,0],(y-K[1,2])*d/K[1,1],d,1.])
     vals.append(f'{x}:{d:.3f} => {w[:3].round(3)}')
    else: vals.append(f'{x}:nan')
   print(y,' '.join(vals))
print('STATUS',robot.status())
